import type { IndustryPack, PackField, PackService, ProductCapabilityRecommendation } from "../index.ts";

const f = (key: string, label: string, type: PackField["type"] = "text", extra: Partial<PackField> = {}): PackField => ({ key, label, type, ...extra });
const asset = (key: string, label: string, pluralLabel: string, fields: readonly PackField[]) => ({ key, label, pluralLabel, fields });
const svc = (key: string, name: string, kind: PackService["kind"], estimatedMinutes?: number): PackService => ({ key, name, kind, ...(estimatedMinutes ? { estimatedMinutes } : {}) });
const rec = (featureKey: string, recommendation: ProductCapabilityRecommendation["recommendation"], rationale: string): ProductCapabilityRecommendation => ({ featureKey, recommendation, rationale });
const conditional = (featureKey: string, rationale: string, answerKey: string, answer: string | boolean): ProductCapabilityRecommendation => ({
  featureKey, recommendation: "conditional", rationale,
  rules: [{ when: { op: "equals", answerKey, value: answer }, recommendation: "normally_recommended" }],
});
const q = (key: string, prompt: string, options: readonly string[]) => ({ key, prompt, answerType: "enum" as const, options });
const yesNo = (key: string, prompt: string) => ({ key, prompt, answerType: "boolean" as const });

